<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { FileText, Plus, Repeat2, Wrench } from 'lucide-vue-next'
import { api, apiError } from '../api/client'
import type { ApiResponse, Company, Contract, Customer, Paginated, ServiceItem } from '../types'
import PageHeader from '../components/PageHeader.vue'
import ModalDialog from '../components/ModalDialog.vue'
import StatusBadge from '../components/StatusBadge.vue'

const contracts=ref<Contract[]>([]);const companies=ref<Company[]>([]);const customers=ref<Customer[]>([]);const services=ref<ServiceItem[]>([]);const error=ref('');const contractModal=ref(false);const serviceModal=ref(false)
const today=new Date().toISOString().slice(0,10)
const serviceForm=reactive({code:'HONORARIOS',name:'Honorários',description:'Serviço recorrente mensal',default_amount:'0.00',default_frequency:'MONTHLY'})
const form=reactive({company_id:'',customer_id:'',service_id:'',code:'',description:'',amount:'0.00',frequency:'MONTHLY',interval_count:1,billing_method:'BOLETO_PIX',due_day:10,start_date:today,end_date:'',issue_days_before_due:10,interest_percent_monthly:'0',fine_percent:'2',discount_amount:'0',fiscal_trigger:'ON_PAYMENT',settings:{}})
const companyName=(id:string)=>companies.value.find(x=>x.id===id)?.trade_name||companies.value.find(x=>x.id===id)?.legal_name||id
const customerName=(id:string)=>customers.value.find(x=>x.id===id)?.name||id
const serviceName=(id:string)=>services.value.find(x=>x.id===id)?.name||id
const money=(v:string)=>Number(v).toLocaleString('pt-BR',{style:'currency',currency:'BRL'})
async function load(){try{const [a,b,c,d]=await Promise.all([api.get<Paginated<Contract>>('/v1/contracts',{params:{per_page:100}}),api.get<ApiResponse<Company[]>>('/v1/companies'),api.get<Paginated<Customer>>('/v1/customers',{params:{per_page:100}}),api.get<ApiResponse<ServiceItem[]>>('/v1/services')]);contracts.value=a.data.data;companies.value=b.data.data;customers.value=c.data.data;services.value=d.data.data;if(!form.company_id&&companies.value[0])form.company_id=companies.value[0].id;if(!form.service_id&&services.value[0])form.service_id=services.value[0].id}catch(e){error.value=apiError(e)}}
async function createService(){try{await api.post('/v1/services',serviceForm);serviceModal.value=false;await load()}catch(e){error.value=apiError(e)}}
async function createContract(){try{const payload={...form,end_date:form.end_date||null};await api.post('/v1/contracts',payload);contractModal.value=false;form.code='';form.description='';await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Contratos e recorrências" subtitle="Regras que geram automaticamente os recebíveis de cada cliente."><button class="btn-secondary" @click="serviceModal=true"><Wrench :size="18"/> Serviço</button><button class="btn-primary" @click="contractModal=true"><Plus :size="18"/> Novo contrato</button></PageHeader><p v-if="error" class="mb-5 rounded-xl bg-rose-50 p-3 text-rose-700">{{error}}</p><div class="table-wrap"><table class="table"><thead><tr><th>Contrato</th><th>Empresa / Cliente</th><th>Serviço</th><th>Recorrência</th><th>Valor</th><th>Status</th></tr></thead><tbody><tr v-for="item in contracts" :key="item.id"><td><p class="font-semibold">{{item.code}}</p><p class="text-xs text-slate-400">Próxima geração: {{new Date(item.next_generation_date+'T12:00:00').toLocaleDateString('pt-BR')}}</p></td><td><p>{{companyName(item.company_id)}}</p><p class="text-xs text-slate-400">{{customerName(item.customer_id)}}</p></td><td>{{serviceName(item.service_id)}}</td><td><div class="flex items-center gap-2"><Repeat2 :size="16" class="text-teal-600"/>{{item.frequency}} · dia {{item.due_day}}</div><p class="text-xs text-slate-400">{{item.billing_method}}</p></td><td class="font-semibold">{{money(item.amount)}}</td><td><StatusBadge :status="item.status"/></td></tr><tr v-if="!contracts.length"><td colspan="6" class="py-12 text-center text-slate-400">Nenhum contrato cadastrado.</td></tr></tbody></table></div>
<ModalDialog :open="serviceModal" title="Cadastrar serviço" @close="serviceModal=false"><form class="space-y-4" @submit.prevent="createService"><div><label class="label">Código</label><input v-model="serviceForm.code" class="input" required/></div><div><label class="label">Nome</label><input v-model="serviceForm.name" class="input" required/></div><div><label class="label">Descrição</label><textarea v-model="serviceForm.description" class="input min-h-20"></textarea></div><div class="grid grid-cols-2 gap-3"><div><label class="label">Valor padrão</label><input v-model="serviceForm.default_amount" type="number" step="0.01" class="input"/></div><div><label class="label">Periodicidade</label><select v-model="serviceForm.default_frequency" class="select"><option>MONTHLY</option><option>QUARTERLY</option><option>SEMIANNUAL</option><option>ANNUAL</option></select></div></div><div class="flex justify-end gap-2"><button type="button" class="btn-secondary" @click="serviceModal=false">Cancelar</button><button class="btn-primary">Salvar</button></div></form></ModalDialog>
<ModalDialog :open="contractModal" title="Cadastrar contrato recorrente" size="xl" @close="contractModal=false"><form class="grid gap-4 md:grid-cols-2" @submit.prevent="createContract"><div><label class="label">Empresa emissora</label><select v-model="form.company_id" class="select" required><option v-for="c in companies" :key="c.id" :value="c.id">{{c.trade_name||c.legal_name}}</option></select></div><div><label class="label">Cliente</label><select v-model="form.customer_id" class="select" required><option value="" disabled>Selecione</option><option v-for="c in customers" :key="c.id" :value="c.id">{{c.name}}</option></select></div><div><label class="label">Serviço</label><select v-model="form.service_id" class="select" required><option v-for="s in services" :key="s.id" :value="s.id">{{s.name}}</option></select></div><div><label class="label">Código do contrato</label><input v-model="form.code" class="input" placeholder="CTR-0001" required/></div><div><label class="label">Valor</label><input v-model="form.amount" type="number" min="0.01" step="0.01" class="input" required/></div><div><label class="label">Forma de cobrança</label><select v-model="form.billing_method" class="select"><option>BOLETO_PIX</option><option>PIX</option><option>BOLETO</option><option>RECEIPT</option><option>MANUAL</option></select></div><div><label class="label">Periodicidade</label><select v-model="form.frequency" class="select"><option>WEEKLY</option><option>BIWEEKLY</option><option>MONTHLY</option><option>BIMONTHLY</option><option>QUARTERLY</option><option>SEMIANNUAL</option><option>ANNUAL</option></select></div><div class="grid grid-cols-2 gap-2"><div><label class="label">Dia vencimento</label><input v-model.number="form.due_day" type="number" min="1" max="31" class="input"/></div><div><label class="label">Emitir antes</label><input v-model.number="form.issue_days_before_due" type="number" min="0" class="input"/></div></div><div><label class="label">Primeiro vencimento</label><input v-model="form.start_date" type="date" class="input" required/></div><div><label class="label">Término opcional</label><input v-model="form.end_date" type="date" class="input"/></div><div class="grid grid-cols-2 gap-2"><div><label class="label">Multa %</label><input v-model="form.fine_percent" type="number" step="0.01" class="input"/></div><div><label class="label">Juros % a.m.</label><input v-model="form.interest_percent_monthly" type="number" step="0.0001" class="input"/></div></div><div><label class="label">Gatilho fiscal</label><select v-model="form.fiscal_trigger" class="select"><option>ON_PAYMENT</option><option>ON_CHARGE</option><option>MANUAL</option></select></div><div class="md:col-span-2"><label class="label">Descrição</label><textarea v-model="form.description" class="input min-h-20"></textarea></div><div class="md:col-span-2 flex justify-end gap-2"><button type="button" class="btn-secondary" @click="contractModal=false">Cancelar</button><button class="btn-primary">Salvar contrato</button></div></form></ModalDialog></template>
